WITH StartData AS (SELECT FUND_SYMBOL, FUND_NAME, RESTORED_ACCU_NAV AS START_NAV, TRADING_DAY AS START_DATE, ROW_NUMBER() OVER(PARTITION BY FUND_SYMBOL ORDER BY TRADING_DAY DESC) as rn FROM FUND_NETVALUE WHERE FUND_NAME LIKE '%易方达蓝筹精选混合%' AND TRADING_DAY <= '2024-12-31' AND RESTORED_ACCU_NAV IS NOT NULL AND FUND_SYMBOL IS NOT NULL AND HISVALID = 1), EndData AS (SELECT FUND_SYMBOL, FUND_NAME, RESTORED_ACCU_NAV AS END_NAV, TRADING_DAY AS END_DATE, ROW_NUMBER() OVER(PARTITION BY FUND_SYMBOL ORDER BY TRADING_DAY DESC) as rn FROM FUND_NETVALUE WHERE FUND_NAME LIKE '%易方达蓝筹精选混合%' AND TRADING_DAY <= '2025-12-31' AND RESTORED_ACCU_NAV IS NOT NULL AND FUND_SYMBOL IS NOT NULL AND HISVALID = 1) SELECT e.FUND_NAME AS `基金名称`, e.FUND_SYMBOL AS `基金代码`, s.START_DATE AS `期初交易日`, e.END_DATE AS `期末交易日`, s.START_NAV AS `期初复权累计净值`, e.END_NAV AS `期末复权累计净值`, CASE WHEN s.START_NAV = 0 THEN NULL ELSE (e.END_NAV / s.START_NAV - 1) * 100 END AS `年度收益率(%)` FROM (SELECT * FROM EndData WHERE rn = 1) e JOIN (SELECT * FROM StartData WHERE rn = 1) s ON e.FUND_SYMBOL = s.FUND_SYMBOL ORDER BY e.FUND_SYMBOL;
200
{table:[['基金名称', '基金代码', '期初交易日', '期末交易日', '期初复权累计净值', '期末复权累计净值', '年度收益率(%)'], ['易方达蓝筹精选混合', '005827.OF', '2024-12-31', '2025-12-31', '1.74', '1.86', '6.86']]}
该查询获取了“易方达蓝筹精选混合”基金在2025年度的复权累计净值区间收益率和相关信息。数据来源于基金净值信息表，筛选条件为基金简称包含“易方达蓝筹精选混合”，并选取每个基金份额在2024年末和2025年末（即对应的最后一个交易日）各自最新且有效的复权累计净值数据，通过份额代码匹配进行连接。查询展示了基金名称、基金代码、2024年末和2025年末的交易日、对应的期初与期末复权累计净值，并采用“年度收益率 = (2025年末复权累计净值 ÷ 2024年末复权累计净值 − 1) × 100%”的公式计算出年度收益率，保留了完整百分数格式。查询结果能够准确反映2025年间该基金的区间收益表现，满足用户需求。
